'use strict';
/* =====================================================================
 * Simulation core (no DOM access). Units: metres, kilograms, seconds.
 * World is y-up, ground plane at y = 0, wall face at x = 0.
 * ===================================================================== */
const Sim = (() => {
  const DT = 1 / 120;
  const INV_DT = 1 / DT;
  const VEL_ITERS = 12;
  const SLOP = 0.003;
  const BETA = 0.25;
  const MAX_PUSH = 3.0;
  const RESTITUTION_THRESHOLD = 0.9;
  const SLEEP_LIN = 0.05;
  const SLEEP_ANG = 0.09;
  const SLEEP_TIME = 0.6;
  const MAX_SPEED = 140;
  const SUPPORT_SCALE = 0.05;
  const CAT_CAR = 1 << 8;
  const BRICK_ALL = 0xff;

  let nextId = 1;
  const resetIds = () => { nextId = 1; };

  function createBody(o) {
    const shapes = o.shapes.map(s => ({ hx: s.hx, hy: s.hy, ox: s.ox || 0, oy: s.oy || 0, wx: 0, wy: 0 }));
    let rad = 0;
    for (const s of shapes) rad = Math.max(rad, Math.hypot(s.ox, s.oy) + Math.hypot(s.hx, s.hy));
    const a = o.a || 0;
    return {
      id: nextId++, idx: 0, kind: o.kind, isCar: o.kind === 'car',
      x: o.x, y: o.y, a, cs: Math.cos(a), sn: Math.sin(a),
      vx: 0, vy: 0, w: 0, bvx: 0, bvy: 0, bw: 0,
      m: o.m, im: 1 / o.m, I: o.I, iI: 1 / o.I,
      fr: o.fr, re: o.re, cat: o.cat, mask: o.mask,
      linDamp: o.linDamp ?? 0.02, angDamp: o.angDamp ?? 0.08,
      shapes, rad,
      awake: true, sleepT: 0, sleepIsland: null, noSleep: false,
      minX: 0, minY: 0, maxX: 0, maxY: 0, cx0: 0, cx1: 0, cy0: 0, cy1: 0, qStamp: 0,
    };
  }

  function wakeBody(b) {
    if (b.awake) return;
    const isl = b.sleepIsland;
    if (isl) {
      for (const m of isl) { m.awake = true; m.sleepT = 0; m.sleepIsland = null; }
    } else { b.awake = true; b.sleepT = 0; }
  }

  function applyImpulse(b, jx, jy, px, py) {
    b.vx += jx * b.im;
    b.vy += jy * b.im;
    b.w += ((px - b.x) * jy - (py - b.y) * jx) * b.iI;
  }

  /* ---------------- Box vs box (SAT + clipping, Box2D-Lite style) ---------------- */
  const makeCV = () => ({ x: 0, y: 0, i1: 0, o1: 0, i2: 0, o2: 0 });
  const INC = [makeCV(), makeCV()], CP1 = [makeCV(), makeCV()], CP2 = [makeCV(), makeCV()];
  const OUT = [{ px: 0, py: 0, sep: 0, fid: 0 }, { px: 0, py: 0, sep: 0, fid: 0 }];
  const CN = { nx: 0, ny: 0 };

  function copyCV(d, s) { d.x = s.x; d.y = s.y; d.i1 = s.i1; d.o1 = s.o1; d.i2 = s.i2; d.o2 = s.o2; }

  function clipSegment(out, inp, nx, ny, offset, clipEdge) {
    let n = 0;
    const d0 = nx * inp[0].x + ny * inp[0].y - offset;
    const d1 = nx * inp[1].x + ny * inp[1].y - offset;
    if (d0 <= 0) copyCV(out[n++], inp[0]);
    if (d1 <= 0) copyCV(out[n++], inp[1]);
    if (d0 * d1 < 0) {
      const t = d0 / (d0 - d1);
      const o = out[n++];
      if (d0 > 0) { copyCV(o, inp[0]); o.i1 = clipEdge; o.i2 = 0; }
      else { copyCV(o, inp[1]); o.o1 = clipEdge; o.o2 = 0; }
      o.x = inp[0].x + t * (inp[1].x - inp[0].x);
      o.y = inp[0].y + t * (inp[1].y - inp[0].y);
    }
    return n;
  }

  function setCV(v, x, y, i2, o2) { v.x = x; v.y = y; v.i1 = 0; v.o1 = 0; v.i2 = i2; v.o2 = o2; }

  function incidentEdge(c, hx, hy, px, py, cs, sn, nx, ny) {
    const lx = -(cs * nx + sn * ny), ly = -(-sn * nx + cs * ny);
    if (Math.abs(lx) > Math.abs(ly)) {
      if (lx >= 0) { setCV(c[0], hx, -hy, 3, 4); setCV(c[1], hx, hy, 4, 1); }
      else { setCV(c[0], -hx, hy, 1, 2); setCV(c[1], -hx, -hy, 2, 3); }
    } else if (ly >= 0) { setCV(c[0], hx, hy, 4, 1); setCV(c[1], -hx, hy, 1, 2); }
    else { setCV(c[0], -hx, -hy, 2, 3); setCV(c[1], hx, -hy, 3, 4); }
    for (let i = 0; i < 2; i++) {
      const v = c[i], x = v.x, y = v.y;
      v.x = px + cs * x - sn * y;
      v.y = py + sn * x + cs * y;
    }
  }

  // Returns number of contact points in OUT; normal (A -> B) in CN. Points with separation up to `margin` are kept (speculative).
  function collideBoxes(ax, ay, ac, as, ahx, ahy, bx, by, bc, bs, bhx, bhy, margin) {
    const dpx = bx - ax, dpy = by - ay;
    const dAx = ac * dpx + as * dpy, dAy = -as * dpx + ac * dpy;
    const dBx = bc * dpx + bs * dpy, dBy = -bs * dpx + bc * dpy;
    const a11 = Math.abs(ac * bc + as * bs), a12 = Math.abs(-ac * bs + as * bc);
    const a21 = Math.abs(-as * bc + ac * bs), a22 = Math.abs(as * bs + ac * bc);
    const faceAx = Math.abs(dAx) - ahx - (a11 * bhx + a12 * bhy);
    const faceAy = Math.abs(dAy) - ahy - (a21 * bhx + a22 * bhy);
    if (faceAx > margin || faceAy > margin) return 0;
    const faceBx = Math.abs(dBx) - (a11 * ahx + a21 * ahy) - bhx;
    const faceBy = Math.abs(dBy) - (a12 * ahx + a22 * ahy) - bhy;
    if (faceBx > margin || faceBy > margin) return 0;

    let axis = 0, sep = faceAx;
    let nx = dAx > 0 ? ac : -ac, ny = dAx > 0 ? as : -as;
    if (faceAy > sep + 0.05 * Math.abs(sep) + 0.01 * ahy) { axis = 1; sep = faceAy; nx = dAy > 0 ? -as : as; ny = dAy > 0 ? ac : -ac; }
    if (faceBx > sep + 0.05 * Math.abs(sep) + 0.01 * bhx) { axis = 2; sep = faceBx; nx = dBx > 0 ? bc : -bc; ny = dBx > 0 ? bs : -bs; }
    if (faceBy > sep + 0.05 * Math.abs(sep) + 0.01 * bhy) { axis = 3; sep = faceBy; nx = dBy > 0 ? -bs : bs; ny = dBy > 0 ? bc : -bc; }

    let fnx, fny, front, snx, sny, side, negSide, posSide, negEdge, posEdge;
    if (axis === 0) {
      fnx = nx; fny = ny; front = ax * fnx + ay * fny + ahx;
      snx = -as; sny = ac; side = ax * snx + ay * sny;
      negSide = -side + ahy; posSide = side + ahy; negEdge = 3; posEdge = 1;
      incidentEdge(INC, bhx, bhy, bx, by, bc, bs, fnx, fny);
    } else if (axis === 1) {
      fnx = nx; fny = ny; front = ax * fnx + ay * fny + ahy;
      snx = ac; sny = as; side = ax * snx + ay * sny;
      negSide = -side + ahx; posSide = side + ahx; negEdge = 2; posEdge = 4;
      incidentEdge(INC, bhx, bhy, bx, by, bc, bs, fnx, fny);
    } else if (axis === 2) {
      fnx = -nx; fny = -ny; front = bx * fnx + by * fny + bhx;
      snx = -bs; sny = bc; side = bx * snx + by * sny;
      negSide = -side + bhy; posSide = side + bhy; negEdge = 3; posEdge = 1;
      incidentEdge(INC, ahx, ahy, ax, ay, ac, as, fnx, fny);
    } else {
      fnx = -nx; fny = -ny; front = bx * fnx + by * fny + bhy;
