    rax: 0, ray: 0, rbx: 0, rby: 0, imA: 0, iIA: 0, imB: 0, iIB: 0, sA: 1, sB: 1,
    mn: 0, mt: 0, pn: 0, pt: 0, pb: 0, bias: 0, pbias: 0, vn0: 0, fr: 0, re: 0,
