        const need = ne + (x1 - x0 + 1) * (y1 - y0 + 1);
        if (need > this.eCap) this._growEntries(need * 2);
        for (let cx = x0; cx <= x1; cx++) {
          for (let cy = y0; cy <= y1; cy++) {
