              const B = bodies[j];
              if (!A.awake && !B.awake) continue;
              if (A.maxX < B.minX || B.maxX < A.minX || A.maxY < B.minY || B.maxY < A.minY) continue;
              if ((A.cx0 > B.cx0 ? A.cx0 : B.cx0) !== cx || (A.cy0 > B.cy0 ? A.cy0 : B.cy0) !== cy) continue;
