          if (A) { A.vx -= c.imA * Px; A.vy -= c.imA * Py; A.w -= c.iIA * (c.rax * Py - c.ray * Px); }
          B.vx += c.imB * Px; B.vy += c.imB * Py; B.w += c.iIB * (c.rbx * Py - c.rby * Px);
