    }

    _integrate() {
      for (const b of this.bodies) {
        if (!b.awake) continue;
        let vx = b.vx, vy = b.vy;
        const sp2 = vx * vx + vy * vy;
        if (sp2 > MAX_SPEED * MAX_SPEED) { const k = MAX_SPEED / Math.sqrt(sp2); vx *= k; vy *= k; b.vx = vx; b.vy = vy; }
