        b.x += (vx + b.bvx) * DT;
        b.y += (vy + b.bvy) * DT;
        b.a += (b.w + b.bw) * DT;
        b.cs = Math.cos(b.a); b.sn = Math.sin(b.a);
        b.bvx = 0; b.bvy = 0; b.bw = 0;
        if (sp2 < SLEEP_LIN * SLEEP_LIN && b.w * b.w < SLEEP_ANG * SLEEP_ANG) b.sleepT += DT;
        else b.sleepT = 0;
      }
    }

    _find(i) {
      const p = this.parent;
      while (p[i] !== i) { p[i] = p[p[i]]; i = p[i]; }
      return i;
    }

    _union(i, j) {
      const a = this._find(i), b = this._find(j);
      if (a !== b) { if (a < b) this.parent[b] = a; else this.parent[a] = b; }
    }

    _islands() {
