      if (this.parent.length < n) { this.parent = new Int32Array(n); this.minT = new Float64Array(n); }
      const parent = this.parent, minT = this.minT;
      for (let i = 0; i < n; i++) { parent[i] = i; minT[i] = Infinity; }
      const C = this.contacts;
      for (let k = 0; k < this.nc; k++) {
        const c = C[k];
        if (c.a && c.a.awake && c.b.awake) this._union(c.a.idx, c.b.idx);
      }
      for (let k = 0; k < this.links.length; k += 2) {
        const a = this.links[k], b = this.links[k + 1];
        if (a.awake && b.awake) this._union(a.idx, b.idx);
