      for (let i = 0; i < n; i++) {
        const b = bodies[i];
        if (!b.awake) continue;
        const r = this._find(i), t = b.noSleep ? 0 : b.sleepT;
        if (t < minT[r]) minT[r] = t;
      }
      let groups = null;
      let awake = 0;
      for (let i = 0; i < n; i++) {
        const b = bodies[i];
        if (!b.awake) continue;
        const r = this._find(i);
        if (minT[r] >= SLEEP_TIME) {
          if (!groups) groups = new Map();
          let g = groups.get(r);
          if (!g) { g = []; groups.set(r, g); }
          g.push(b);
        } else awake++;
      }
      if (groups) {
        for (const g of groups.values()) {
          for (const b of g) { b.awake = false; b.vx = 0; b.vy = 0; b.w = 0; b.sleepIsland = g; }
        }
      }
      this.awakeCount = awake;
      this.sleepingCount = n - awake;
    }

    raycast(ox, oy, dx, dy, maxT, mask, ignore) {
      let best = maxT, hit = false, hb = null, hnx = 0, hny = 1;
      if (dy < -1e-9 && oy >= 0) {
        const t = -oy / dy;
        if (t <= best) { best = t; hit = true; }
      }
      const ex = ox + dx * maxT, ey = oy + dy * maxT, inv = this.invCell;
      const x0 = Math.floor(Math.min(ox, ex) * inv), x1 = Math.floor(Math.max(ox, ex) * inv);
      const y0 = Math.floor(Math.min(oy, ey) * inv), y1 = Math.floor(Math.max(oy, ey) * inv);
      const stamp = ++this.queryStamp;
      for (let cx = x0; cx <= x1; cx++) {
        for (let cy = y0; cy <= y1; cy++) {
          for (let e = this.head[this._hash(cx, cy)]; e !== -1; e = this.eNext[e]) {
            if (this.eCX[e] !== cx || this.eCY[e] !== cy) continue;
            const B = this.bodies[this.eBody[e]];
            if (B.qStamp === stamp || B === ignore || !(B.cat & mask)) continue;
            B.qStamp = stamp;
            for (const s of B.shapes) {
              const rx = ox - s.wx, ry = oy - s.wy;
              const lox = B.cs * rx + B.sn * ry, loy = -B.sn * rx + B.cs * ry;
              const ldx = B.cs * dx + B.sn * dy, ldy = -B.sn * dx + B.cs * dy;
              let tmin = -Infinity, tmax = Infinity, lnx = 0, lny = 0;
              if (Math.abs(ldx) < 1e-9) { if (Math.abs(lox) > s.hx) continue; }
              else {
                let t1 = (-s.hx - lox) / ldx, t2 = (s.hx - lox) / ldx;
                if (t1 > t2) { const q = t1; t1 = t2; t2 = q; }
                if (t1 > tmin) { tmin = t1; lnx = ldx > 0 ? -1 : 1; lny = 0; }
                if (t2 < tmax) tmax = t2;
              }
              if (Math.abs(ldy) < 1e-9) { if (Math.abs(loy) > s.hy) continue; }
              else {
                let t1 = (-s.hy - loy) / ldy, t2 = (s.hy - loy) / ldy;
                if (t1 > t2) { const q = t1; t1 = t2; t2 = q; }
                if (t1 > tmin) { tmin = t1; lnx = 0; lny = ldy > 0 ? -1 : 1; }
                if (t2 < tmax) tmax = t2;
              }
              if (tmin > tmax || tmin < 0 || tmin >= best) continue;
              best = tmin; hit = true; hb = B;
              hnx = B.cs * lnx - B.sn * lny; hny = B.sn * lnx + B.cs * lny;
            }
          }
