+            }
+          }
+        }
+      }
+      if (!hit) return null;
+      RAY.t = best; RAY.body = hb; RAY.nx = hb ? hnx : 0; RAY.ny = hb ? hny : 1;
+      return RAY;
+    }
+
+    step() {
+      this.events.length = 0;
+      this.links.length = 0;
+      const pc = this.prevContacts; this.prevContacts = this.contacts; this.contacts = pc;
