const RUNUP = 20;          // m between car front and wall face at rest
const RELEASE_X = -1.0;    // tow cable releases when the car front reaches this x
const BRAKE_DELAY = 0.25;  // s after first contact before the wheels lock
const ROLL_RES = 0.012;    // rolling resistance coefficient
const GAP = 0.002;         // horizontal joint between dry-stacked bricks
const G0 = 9.81;           // design gravity for suspension sizing and g readouts

function hashUnit(a, b, c) {
  let h = Math.imul(a ^ 0x9e3779b9, 0x85ebca6b) ^ Math.imul(b + 0x632be5ab, 0xc2b2ae35) ^ Math.imul(c + 0x27d4eb2f, 0x165667b1);
