    this.world.postSolve = (C, nc) => this._afterSolve(C, nc);

    this.state = 'ready';
    this.phase = 'READY';
    this.released = false; this.releaseTime = -1;
    this.impactTime = -1; this.impactSpeed = 0;
    this.braking = false;
    this.crushEnergy = 0; this.crush = 0;
    this.glassEnergy = 0; this.glassDamage = 0;
    this.preVx = 0; this.prevVx = 0; this.accFilt = 0; this.peakDecel = 0;
    this.quietTime = 0; this.completeTime = -1;
    this.minSpeedAfterImpact = Infinity;
    this.stats = { moving: 0, displaced: 0, throw: 0, brickPx: 0, peakBrickPx: 0, total: this.bricks.length };
    this.history = [];
    this.fx = [];
