  }

  get time() { return this.world.time; }

  start() { if (this.state === 'ready') { this.state = 'running'; this.phase = 'TOWING'; } }

  _buildCar() {
    const P = this.P;
    const sx = P.carWidth / 4.2, sy = P.carHeight / 1.45;
    this.sx = sx; this.sy = sy;
    const comX = 0.15 * sx, comY = 0.55 * sy;
    const m = P.carMass, len = P.carWidth, hgt = P.carHeight;
    const shapes = [
      { hx: 2.1 * sx, hy: 0.345 * sy, ox: -comX, oy: 0.515 * sy - comY },              // chassis, bumper to bumper
      { hx: 1.025 * sx, hy: 0.295 * sy, ox: -0.275 * sx - comX, oy: 1.155 * sy - comY }, // cabin / greenhouse
    ];
    const car = createBody({
      kind: 'car', x: -RUNUP - (2.1 * sx - comX), y: comY, m, I: m * (len * len + hgt * hgt) / 12 * 0.72,
      fr: 0.45, re: 0.1, cat: CAT_CAR, mask: BRICK_ALL, shapes, linDamp: 0, angDamp: 0.4,
    });
    car.noSleep = true;
    car.comX = comX; car.comY = comY;
    car.frontLocal = 2.1 * sx - comX;
    car.rearLocal = -2.1 * sx - comX;
    this.chassisFront0 = car.frontLocal;
    this.chassisRear0 = car.rearLocal;
    this.maxCrush = 0.75 * sx;
    this.crushForce = 165 * m;

    const r = 0.33 * sy, hpY = 0.62 * sy - comY;
    const xr = -1.38 * sx, xf = 1.22 * sx;
    const fracF = (comX - xr) / (xf - xr);
    const Ls = 0.29 * sy, comp = 0.12 * sy;
    const mk = (ax, frac, front) => {
      const load = frac * m * G0, k = load / comp;
      return {
        front, lx: ax - comX, ly: hpY, r, L0: Ls + comp, Lmax: Ls + comp + 0.04 * sy, Lmin: 0.08 * sy,
        k, c: 2 * 0.38 * Math.sqrt(k * frac * m), kb: 12 * k,
        len: Ls, contact: true, angle: 0, omega: 0, skid: false, Fn: load, hitX: 0, hitY: 0, onBrick: false, mark: null,
      };
