  _buildWall() {
    const P = this.P, bw = P.brickW, bh = P.brickH, cols = P.cols;
    this.wallX0 = 0; this.wallX1 = cols * bw; this.wallH = P.rows * bh;
    this.bricks = [];
    for (let L = 0; L < P.layers; L++) {
      const island = [];
      for (let r = 0; r < P.rows; r++) {
        const y = bh * (r + 0.5);
        const pieces = [];
        if ((r + L) % 2 === 0) {
          for (let i = 0; i < cols; i++) pieces.push(bw * (i + 0.5), bw);
        } else {
          pieces.push(bw * 0.25, bw * 0.5);
          for (let i = 0; i < cols - 1; i++) pieces.push(bw * (i + 1), bw);
          pieces.push(this.wallX1 - bw * 0.25, bw * 0.5);
        }
        for (let k = 0; k < pieces.length; k += 2) {
          const cx = pieces[k], w = pieces[k + 1];
          const m = P.brickMass * (w / bw);
