            kind: 'brick', x: cx, y, m, I: m * (w * w + bh * bh) / 12, fr: P.brickFriction, re: P.brickRestitution,
            cat: 1 << L, mask: (1 << L) | CAT_CAR, shapes: [{ hx: w / 2 - GAP / 2, hy: bh / 2 }],
          });
