  _carForces(dt) {
    const car = this.car, P = this.P, w = this.world;
    if (!car.awake) return;
    const cs = car.cs, sn = car.sn;

    if (!this.released) {
      if (this.frontX() >= RELEASE_X || this.impactTime >= 0) { this.released = true; this.releaseTime = w.time; }
