      const sp = Math.sqrt(v2), F = 0.5 * 1.2 * 0.31 * 2.2 * this.sy * v2;
      const dvd = Math.min(sp, F * dt * car.im);
      car.vx -= dvd * car.vx / sp; car.vy -= dvd * car.vy / sp;
