        const ox = hpx + fx * off, oy = hpy + fy * off;
        const hit = w.raycast(ox, oy, dx, dy, rayLen, BRICK_ALL, car);
        if (!hit) continue;
        const L = hit.t - Math.sqrt(r * r - off * off);
        if (L < bestL) { bestL = L; bx = ox + dx * hit.t; by = oy + dy * hit.t; bnx = hit.nx; bny = hit.ny; hitBody = hit.body; }
      }
      if (bestL > wh.Lmax) {
        wh.contact = false; wh.skid = false; wh.Fn = 0; wh.onBrick = false;
        wh.len += (wh.Lmax - wh.len) * 0.35;
        if (braking) wh.omega = 0; else wh.omega *= 0.995;
        wh.angle -= wh.omega * dt;
        wh.mark = null;
        continue;
      }
      // A sleeping brick is woken and treated as fixed for this step (its contacts were not generated yet).
      let other = null;
      if (hitBody) {
        if (hitBody.awake) { other = hitBody; w.links.push(car, other); }
        else wakeBody(hitBody);
      }
      const L = bestL;
      const rx = bx - car.x, ry = by - car.y;
      let vrx = car.vx - car.w * ry, vry = car.vy + car.w * rx;
      if (other) { vrx -= other.vx - other.w * (by - other.y); vry -= other.vy + other.w * (bx - other.x); }
      const compRate = vrx * dx + vry * dy;
      let F = wh.k * (wh.L0 - L) + wh.c * compRate;
      if (L < wh.Lmin) F += wh.kb * (wh.Lmin - L) + 3 * wh.c * compRate;
      if (F < 0) F = 0;
      const Fmax = 30 * car.m * G0;
      if (F > Fmax) F = Fmax;
      const J = F * dt;
      applyImpulse(car, -dx * J, -dy * J, bx, by);
      if (other) applyImpulse(other, dx * J, dy * J, bx, by);

      // Tyre force along the contact surface: rolling resistance, or locked-wheel sliding friction when braking.
      const fn = fx * bnx + fy * bny;
      let tx = fx - fn * bnx, ty = fy - fn * bny;
      const tl = Math.hypot(tx, ty);
      let vt = 0;
      if (tl > 1e-6) {
        tx /= tl; ty /= tl;
        vrx = car.vx - car.w * ry; vry = car.vy + car.w * rx;
        let kt = car.im + car.iI * (rx * ty - ry * tx) ** 2;
        if (other) {
          const ox = bx - other.x, oy = by - other.y;
          vrx -= other.vx - other.w * oy; vry -= other.vy + other.w * ox;
          kt += other.im + other.iI * (ox * ty - oy * tx) ** 2;
        }
        vt = vrx * tx + vry * ty;
        const mu = braking ? (hitBody ? Math.sqrt(P.groundFriction * P.brickFriction) : P.groundFriction) : ROLL_RES;
        const lim = mu * J;
        let jt = -vt / kt;
        if (jt > lim) jt = lim; else if (jt < -lim) jt = -lim;
        applyImpulse(car, tx * jt, ty * jt, bx, by);
        if (other) applyImpulse(other, -tx * jt, -ty * jt, bx, by);
      }

      wh.contact = true; wh.Fn = F; wh.hitX = bx; wh.hitY = by; wh.onBrick = !!hitBody;
      wh.len = Math.max(L, wh.Lmin * 0.5);
      wh.omega = braking ? 0 : (vrx * fx + vry * fy) / r;
      wh.angle -= wh.omega * dt;
      wh.skid = braking && Math.abs(vt) > 0.35;
      if (wh.skid && !hitBody) {
        if (!wh.mark) { wh.mark = { x0: bx, x1: bx, front: wh.front }; this.skidMarks.push(wh.mark); }
        wh.mark.x1 = bx;
      } else wh.mark = null;
    }
  }

  _afterSolve(C, nc) {
    const car = this.car, w = this.world;
    for (let k = 0; k < nc; k++) {
      const c = C[k];
      if (!c.carContact || c.pn <= 0) continue;
      if (this.impactTime < 0) { this.impactTime = w.time; this.impactSpeed = Math.abs(this.preVx); }
      const e = 0.5 * c.pn * Math.max(0, -c.vn0);
      if (e <= 0) continue;
      if (c.carShape === 0) {
        const lx = car.cs * (c.px - car.x) + car.sn * (c.py - car.y);
        if (lx > this.chassisFront0 - 1.3 * this.sx) this.crushEnergy += e;
      } else this.glassEnergy += e;
    }
    const target = Math.min(this.maxCrush, this.crushEnergy / this.crushForce);
    if (target > this.crush + 0.001) {
      this.crush = target;
      const s = car.shapes[0], front = this.chassisFront0 - target, rear = this.chassisRear0;
      s.hx = (front - rear) / 2; s.ox = (front + rear) / 2;
    }
    this.glassDamage = Math.min(1, this.glassEnergy / 900);
    for (const ev of w.events) {
      if (ev.e > 60) {
        if (ev.a && ev.a.kind === 'brick') ev.a.damage += ev.e;
        if (ev.b.kind === 'brick') ev.b.damage += ev.e;
      }
      if (this.fx.length < 600) this.fx.push(ev);
    }
  }

  _complete() {
    if (this.state === 'complete') return;
    this.state = 'complete';
    this.phase = 'COMPLETE';
    this.completeTime = this.world.time;
  }

  _telemetryStep() {
    const w = this.world, car = this.car, t = w.time;
    const a = (this.prevVx - car.vx) * INV_DT;
    this.prevVx = car.vx;
    this.accFilt += (a - this.accFilt) * 0.18;
    if (this.impactTime >= 0) {
      if (t - this.impactTime < 2) this.peakDecel = Math.max(this.peakDecel, this.accFilt / G0);
      this.minSpeedAfterImpact = Math.min(this.minSpeedAfterImpact, car.vx);
    }

    let moving = 0, displaced = 0, thr = 0, px = 0;
    let maxSp = car.awake ? Math.hypot(car.vx, car.vy) : 0;
    for (const b of this.bricks) {
      if (b.awake) {
        const sp = Math.hypot(b.vx, b.vy);
        if (sp > 0.1 || Math.abs(b.w) > 0.25) moving++;
        if (sp > maxSp) maxSp = sp;
        px += b.m * b.vx;
      }
      const ddx = b.x - b.x0, ddy = b.y - b.y0;
      if (ddx * ddx + ddy * ddy > 0.0225 || b.cs < 0.985) displaced++;
      if (ddx > thr) thr = ddx;
    }
    const st = this.stats;
    st.moving = moving; st.displaced = displaced; st.throw = thr; st.brickPx = px;
    if (px > st.peakBrickPx) st.peakBrickPx = px;

    if (this.impactTime < 0) this.phase = this.released ? 'COASTING' : 'TOWING';
    else this.phase = t - this.impactTime < 0.5 ? 'IMPACT' : 'SETTLING';
    if (this.impactTime >= 0 && t > this.impactTime + 1.0) car.noSleep = false;

    if (maxSp < 0.12) this.quietTime += DT; else this.quietTime = 0;
    if (this.impactTime >= 0 && t > this.impactTime + 1.5 && (w.awakeCount === 0 || this.quietTime > 1.5)) this._complete();
    if (t > 60) this._complete();

    if ((w.steps & 1) === 0) this.history.push(t, Math.hypot(car.vx, car.vy), moving);
  }

  step() {
    if (this.state !== 'running') return false;
    this.preVx = this.car.vx;
    this.world.step();
    this._telemetryStep();
    return true;
  }
}

return { DT, PARAMS, DEFAULTS, RUNUP, RELEASE_X, G0, Experiment, World, createBody, hashUnit };

