    this.world.add(car);
  }

  _buildWall() {
    const P = this.P, bw = P.brickW, bh = P.brickH, cols = P.cols;
    this.wallX0 = 0; this.wallX1 = cols * bw; this.wallH = P.rows * bh;
    this.bricks = [];
    for (let L = 0; L < P.layers; L++) {
      const island = [];
      for (let r = 0; r < P.rows; r++) {
        const y = bh * (r + 0.5);
        const pieces = [];
        if ((r + L) % 2 === 0) {
          for (let i = 0; i < cols; i++) pieces.push(bw * (i + 0.5), bw);
        } else {
          pieces.push(bw * 0.25, bw * 0.5);
          for (let i = 0; i < cols - 1; i++) pieces.push(bw * (i + 1), bw);
          pieces.push(this.wallX1 - bw * 0.25, bw * 0.5);
        }
        for (let k = 0; k < pieces.length; k += 2) {
          const cx = pieces[k], w = pieces[k + 1];
          const m = P.brickMass * (w / bw);
          const b = createBody({
            kind: 'brick', x: cx, y, m, I: m * (w * w + bh * bh) / 12, fr: P.brickFriction, re: P.brickRestitution,
            cat: 1 << L, mask: (1 << L) | CAT_CAR, shapes: [{ hx: w / 2 - GAP / 2, hy: bh / 2 }],
          });
          b.layer = L; b.row = r; b.x0 = cx; b.y0 = y; b.half = w < bw * 0.99;
          b.tint = hashUnit(L * 131 + r, k, 7);
          b.damage = 0;
          b.awake = false; b.sleepIsland = island;
          island.push(b);
          this.world.add(b);
          this.bricks.push(b);
        }
      }
    }
  }

  frontX() {
    const c = this.car;
    return c.x + c.cs * (this.chassisFront0 - this.crush) - c.sn * c.shapes[0].oy;
  }

  _carForces(dt) {
    const car = this.car, P = this.P, w = this.world;
    if (!car.awake) return;
    const cs = car.cs, sn = car.sn;

    if (!this.released) {
      if (this.frontX() >= RELEASE_X || this.impactTime >= 0) { this.released = true; this.releaseTime = w.time; }
