        wh.len += (wh.Lmax - wh.len) * 0.35;
        if (braking) wh.omega = 0; else wh.omega *= 0.995;
        wh.angle -= wh.omega * dt;
        wh.mark = null;
        continue;
      }
      // A sleeping brick is woken and treated as fixed for this step (its contacts were not generated yet).
      let other = null;
      if (hitBody) {
        if (hitBody.awake) { other = hitBody; w.links.push(car, other); }
        else wakeBody(hitBody);
      }
      const L = bestL;
      const rx = bx - car.x, ry = by - car.y;
      let vrx = car.vx - car.w * ry, vry = car.vy + car.w * rx;
      if (other) { vrx -= other.vx - other.w * (by - other.y); vry -= other.vy + other.w * (bx - other.x); }
      const compRate = vrx * dx + vry * dy;
      let F = wh.k * (wh.L0 - L) + wh.c * compRate;
      if (L < wh.Lmin) F += wh.kb * (wh.Lmin - L) + 3 * wh.c * compRate;
      if (F < 0) F = 0;
      const Fmax = 30 * car.m * G0;
      if (F > Fmax) F = Fmax;
      const J = F * dt;
      applyImpulse(car, -dx * J, -dy * J, bx, by);
      if (other) applyImpulse(other, dx * J, dy * J, bx, by);

      // Tyre force along the contact surface: rolling resistance, or locked-wheel sliding friction when braking.
      const fn = fx * bnx + fy * bny;
      let tx = fx - fn * bnx, ty = fy - fn * bny;
      const tl = Math.hypot(tx, ty);
      let vt = 0;
      if (tl > 1e-6) {
        tx /= tl; ty /= tl;
        vrx = car.vx - car.w * ry; vry = car.vy + car.w * rx;
        let kt = car.im + car.iI * (rx * ty - ry * tx) ** 2;
        if (other) {
          const ox = bx - other.x, oy = by - other.y;
          vrx -= other.vx - other.w * oy; vry -= other.vy + other.w * ox;
