const fs = require('fs');
const html = fs.readFileSync(__dirname + '/index.html', 'utf8');
const m = html.match(/<script id="sim-core">([\s\S]*?)<\/script>/);
const Sim = new Function(m[1] + '\nreturn Sim;')();

function run(over, seconds, label) {
  const exp = new Sim.Experiment(Object.assign({}, Sim.DEFAULTS, over));
  exp.start();
  const t0 = performance.now();
  let maxPen = 0, maxStepMs = 0, nan = false;
  const steps = Math.round(seconds / Sim.DT);
  const marks = {};
  for (let i = 0; i < steps && exp.state === 'running'; i++) {
    const s0 = performance.now();
    exp.step();
    const ms = performance.now() - s0;
    if (ms > maxStepMs) maxStepMs = ms;
    const w = exp.world;
    for (let k = 0; k < w.nc; k++) { const c = w.contacts[k]; if (-c.sep > maxPen) maxPen = -c.sep; }
    for (const b of w.bodies) if (!Number.isFinite(b.x + b.y + b.a)) nan = true;
    const t = w.time;
    for (const tm of [1, 2, 3, 4, 6, 10]) if (!marks[tm] && t >= tm) marks[tm] = `t=${tm}s v=${exp.car.vx.toFixed(2)} x=${exp.frontX().toFixed(2)} moving=${exp.stats.moving} awake=${w.awakeCount}`;
  }
  const el = performance.now() - t0;
  const car = exp.car;
  const sig = exp.world.bodies.reduce((s, b) => s + b.x * 1.3 + b.y * 2.7 + b.a, 0);
  console.log(`\n== ${label}`);
  console.log(Object.values(marks).join('\n'));
  console.log(`state=${exp.state} t=${exp.time.toFixed(2)} impactT=${exp.impactTime.toFixed(3)} impactV=${exp.impactSpeed.toFixed(2)} car vx=${car.vx.toFixed(3)} carX=${car.x.toFixed(2)} carY=${car.y.toFixed(3)} carAng=${(car.a * 57.3).toFixed(1)}deg`);
  console.log(`peakDecel=${exp.peakDecel.toFixed(1)}g crush=${(exp.crush * 100).toFixed(1)}cm glass=${exp.glassDamage.toFixed(2)} displaced=${exp.stats.displaced}/${exp.stats.total} throw=${exp.stats.throw.toFixed(2)} peakPx=${exp.stats.peakBrickPx.toFixed(0)} minBrickY=${Math.min(...exp.bricks.map(b => b.y)).toFixed(3)}`);
  console.log(`maxPen=${maxPen.toFixed(4)} nan=${nan} wall=${el.toFixed(0)}ms steps=${exp.world.steps} avg=${(el / exp.world.steps).toFixed(3)}ms max=${maxStepMs.toFixed(1)}ms sig=${sig.toFixed(6)}`);
  return sig;
}

const which = process.argv[2] || 'default';
if (which === 'default') {
  const a = run({}, 30, 'defaults');
  const b = run({}, 30, 'defaults (repeat)');
  console.log('\ndeterministic:', a === b);
} else if (which === 'range') {
  run({ speed: 5, brickMass: 12, layers: 5 }, 30, 'slow heavy thick');
  run({ speed: 45, brickMass: 0.5, layers: 1 }, 30, 'fast light thin');
  run({ speed: 45, cols: 24, rows: 16, layers: 5, brickMass: 12 }, 20, 'max wall fast heavy');
  run({ speed: 8, cols: 4, rows: 3, layers: 1 }, 30, 'tiny wall slow');
}

