  for (let s = 0; s < 600; s++) w.step();
  console.log('stack', bs.map(b => `(${b.x.toFixed(3)},${b.y.toFixed(3)},${b.a.toFixed(3)})`).join(' '), 'awake', w.awakeCount);
}
// 2) sliding box hits a box
{
  const w = new Sim.World({ gravity: 9.81, groundFriction: 0.85 });
  const a = Sim.createBody({ kind: 'brick', x: -2, y: 0.5, m: 100, I: 100*(1+1)/12, fr: 0.5, re: 0.1, cat: 1, mask: 1, shapes: [{hx: 0.5, hy: 0.5}] });
  const b = Sim.createBody({ kind: 'brick', x: 0, y: 0.12, m: 2.5, I: 2.5*(0.25+0.0576)/12, fr: 0.72, re: 0.18, cat: 1, mask: 1, shapes: [{hx: 0.25, hy: 0.12}] });
  w.add(a); w.add(b); a.vx = 20;
  for (let s = 0; s < 30; s++) { w.step(); if (s > 5 && s < 20) console.log(s, 'A', a.x.toFixed(3), a.vx.toFixed(2), 'B', b.x.toFixed(3), b.vx.toFixed(2), b.y.toFixed(3), 'nc', w.nc, w.contacts.slice(0, w.nc).filter(c=>c.a).map(c => `n(${c.nx.toFixed(2)},${c.ny.toFixed(2)}) s=${c.sep.toFixed(3)} pn=${c.pn.toFixed(1)}`).join(' | ')); }
}
// 3) trace experiment impact
{
  const exp = new Sim.Experiment(Sim.DEFAULTS); exp.start();
  while (exp.impactTime < 0 && exp.time < 5) exp.step();
  for (let s = 0; s < 12; s++) {
    exp.step();
    const w = exp.world, car = exp.car;
    const cc = w.contacts.slice(0, w.nc).filter(c => c.carContact);
    let worst = cc.reduce((m, c) => (c.sep < m.sep ? c : m), { sep: 1 });
    console.log(s, 'car vx', car.vx.toFixed(2), 'w', car.w.toFixed(2), 'y', car.y.toFixed(3), 'carC', cc.length, 'worst', worst.sep.toFixed(3), worst.nx?.toFixed(2), worst.ny?.toFixed(2), 'shape', worst.carShape, 'pn', worst.pn?.toFixed(0), 'sA', worst.sA, 'sB', worst.sB, 'crush', exp.crush.toFixed(3));
  }
}
