const RAY = { t: 0, body: null, nx: 0, ny: 0 };

// Open-addressing table: contact feature key -> index of that contact in the previous step (warm starting).
class WarmTable {
  constructor(bits) { this._alloc(bits); }
  _alloc(bits) {
    this.size = 1 << bits; this.mask = this.size - 1; this.count = 0;
    this.keys = new Float64Array(this.size).fill(-1);
    this.hashes = new Int32Array(this.size);
    this.vals = new Int32Array(this.size);
  }
  clear() { if (this.count) { this.keys.fill(-1); this.count = 0; } }
  set(key, h, v) {
    if (this.count * 2 > this.size) this._grow();
    const keys = this.keys, mask = this.mask;
    let i = h & mask;
