'use strict';
(() => {
  const { Experiment, PARAMS, DEFAULTS, DT, RUNUP, RELEASE_X, G0, hashUnit } = Sim;
  const clamp = (v, a, b) => (v < a ? a : v > b ? b : v);

  // Visual-only PRNG: dust and chips never feed back into the physics state.
  function mulberry32(seed) {
    return () => {
      seed = (seed + 0x6d2b79f5) | 0;
      let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
  }

  /* =====================================================================
   * Renderer
   * ===================================================================== */
  const canvas = document.getElementById('scene');
  const ctx = canvas.getContext('2d');
  let W = 1, H = 1, DPR = 1, groundY = 1, floorTop = 1;
  const cam = { x: 0, s: 40, shakeX: 0, shakeY: 0 };
  const view = { cx: 0, right: 0, top: 64 };
  const LAYER_DX = 0.05, LAYER_DY = 0.035;
  const NB = 8;
  const X = (wx) => (wx - cam.x) * cam.s + view.cx + cam.shakeX;
  const Y = (wy) => groundY - wy * cam.s + cam.shakeY;

  let hazardPattern = null;
  function makeHazardPattern() {
    const c = document.createElement('canvas');
    c.width = 16; c.height = 16;
    const g = c.getContext('2d');
    g.fillStyle = '#d9a520'; g.fillRect(0, 0, 16, 16);
    g.fillStyle = '#16181b';
    g.beginPath(); g.moveTo(0, 0); g.lineTo(8, 0); g.lineTo(0, 8); g.closePath(); g.fill();
    g.beginPath(); g.moveTo(16, 0); g.lineTo(16, 8); g.lineTo(8, 16); g.lineTo(0, 16); g.closePath(); g.fill();
    hazardPattern = ctx.createPattern(c, 'repeat');
  }

  function buildBrickLook(exp) {
    const layers = exp.P.layers;
    const groups = [], all = [], colors = [];
    for (let L = 0; L < layers; L++) {
      groups.push(Array.from({ length: NB }, () => []));
      all.push([]);
      const row = [];
      for (let k = 0; k < NB; k++) {
        const u = (k + 0.5) / NB;
        const h = 9 + u * 13, s = 52 + (1 - u) * 12, l = 45 - u * 9 - L * 4.5;
        row.push(`hsl(${h.toFixed(1)} ${s.toFixed(0)}% ${l.toFixed(1)}%)`);
      }
      colors.push(row);
    }
    exp.bricks.forEach((b, i) => {
      b.ri = i;
      groups[b.layer][Math.min(NB - 1, Math.floor(b.tint * NB))].push(b);
      all[b.layer].push(b);
    });
    return { groups, all, colors, corners: new Float32Array(exp.bricks.length * 8) };
  }

  function computeCorners(exp, look) {
    const S = cam.s, C = look.corners;
    for (const b of exp.bricks) {
      const s = b.shapes[0];
      const px = X(b.x) + b.layer * LAYER_DX * S, py = Y(b.y) - b.layer * LAYER_DY * S;
      const ax = b.cs * s.hx * S, ay = -b.sn * s.hx * S, bx = -b.sn * s.hy * S, by = -b.cs * s.hy * S;
      const o = b.ri * 8;
      C[o] = px + ax + bx; C[o + 1] = py + ay + by;
      C[o + 2] = px - ax + bx; C[o + 3] = py - ay + by;
      C[o + 4] = px - ax - bx; C[o + 5] = py - ay - by;
      C[o + 6] = px + ax - bx; C[o + 7] = py + ay - by;
    }
  }

  function quad(C, o) {
    ctx.moveTo(C[o], C[o + 1]); ctx.lineTo(C[o + 2], C[o + 3]);
    ctx.lineTo(C[o + 4], C[o + 5]); ctx.lineTo(C[o + 6], C[o + 7]); ctx.closePath();
  }

  // Edge whose outward normal points most upward (top) or downward (bottom), as corner index pairs.
  function edgeFor(b, top) {
    const c = b.cs, n = b.sn;
    let e;
    if (Math.abs(c) >= Math.abs(n)) e = c > 0 ? 0 : 2; else e = n > 0 ? 3 : 1;
    return top ? e : (e + 2) % 4;
  }

  function drawBricks(exp, look) {
    const S = cam.s, C = look.corners;
    const lw = Math.max(0.7, S * 0.013);
    for (let L = exp.P.layers - 1; L >= 0; L--) {
      const list = look.all[L];
      for (let k = 0; k < NB; k++) {
        const g = look.groups[L][k];
        if (!g.length) continue;
        ctx.beginPath();
        for (const b of g) quad(C, b.ri * 8);
        ctx.fillStyle = look.colors[L][k];
        ctx.fill();
      }
      ctx.lineJoin = 'round';
      ctx.beginPath();
      for (const b of list) quad(C, b.ri * 8);
      ctx.strokeStyle = L === 0 ? 'rgba(34,18,13,0.92)' : 'rgba(24,13,10,0.9)';
      ctx.lineWidth = lw;
      ctx.stroke();
      if (S > 18) {
        const inset = lw * 0.9;
        ctx.beginPath();
        for (const b of list) {
          const e = edgeFor(b, true), o = b.ri * 8, i0 = o + e * 2, i1 = o + ((e + 1) % 4) * 2;
          ctx.moveTo(C[i0], C[i0 + 1] + inset); ctx.lineTo(C[i1], C[i1 + 1] + inset);
        }
        ctx.strokeStyle = L === 0 ? 'rgba(255,214,180,0.28)' : 'rgba(255,214,180,0.14)';
        ctx.lineWidth = Math.max(0.6, S * 0.012);
        ctx.stroke();
        ctx.beginPath();
        for (const b of list) {
          const e = edgeFor(b, false), o = b.ri * 8, i0 = o + e * 2, i1 = o + ((e + 1) % 4) * 2;
          ctx.moveTo(C[i0], C[i0 + 1] - inset); ctx.lineTo(C[i1], C[i1 + 1] - inset);
        }
        ctx.strokeStyle = 'rgba(40,12,5,0.35)';
        ctx.lineWidth = Math.max(0.8, S * 0.02);
        ctx.stroke();
        ctx.beginPath();
        let any = false;
        for (const b of list) {
          if (b.damage < 150) continue;
          any = true;
          const o = b.ri * 8;
          const cracks = b.damage > 700 ? 2 : 1;
          for (let q = 0; q < cracks; q++) {
            const u1 = 0.2 + 0.6 * hashUnit(b.id, q, 11), u2 = 0.2 + 0.6 * hashUnit(b.id, q, 23), j = hashUnit(b.id, q, 37) - 0.5;
            const x1 = C[o] + (C[o + 2] - C[o]) * u1, y1 = C[o + 1] + (C[o + 3] - C[o + 1]) * u1;
            const x3 = C[o + 6] + (C[o + 4] - C[o + 6]) * u2, y3 = C[o + 7] + (C[o + 5] - C[o + 7]) * u2;
            const mx = (x1 + x3) / 2 + (C[o] - C[o + 2]) * j * 0.18, my = (y1 + y3) / 2 + (C[o + 1] - C[o + 3]) * j * 0.18;
            ctx.moveTo(x1, y1); ctx.lineTo(mx, my); ctx.lineTo(x3, y3);
          }
        }
        if (any) { ctx.strokeStyle = 'rgba(30,12,8,0.75)'; ctx.lineWidth = Math.max(0.6, S * 0.008); ctx.stroke(); }
      }
    }
  }

  function drawBackground(exp, t) {
    const S = cam.s;
    const band = clamp(0.5 * S, 14, 46);
    floorTop = groundY - band;
    let g = ctx.createLinearGradient(0, 0, 0, floorTop);
    g.addColorStop(0, '#0b0f14'); g.addColorStop(0.55, '#121921'); g.addColorStop(1, '#1b232d');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, W, floorTop);

    // Far hall wall (parallax depth 0.45)
    const p = 0.45, Sp = S * p;
    const bx = (wx) => (wx - cam.x) * Sp + view.cx + cam.shakeX * 0.4;
    const by = (wy) => floorTop - wy * Sp + cam.shakeY * 0.4;
    const xL = cam.x - view.cx / Sp, xR = cam.x + (W - view.cx) / Sp;
    for (let x = Math.floor(xL / 8) * 8; x <= xR + 8; x += 8) {
      const lx = bx(x);
      const rg = ctx.createRadialGradient(lx, 40, 0, lx, 40, 7 * Sp);
      rg.addColorStop(0, 'rgba(190,210,235,0.10)'); rg.addColorStop(1, 'rgba(190,210,235,0)');
      ctx.fillStyle = rg;
      ctx.fillRect(lx - 7 * Sp, 0, 14 * Sp, floorTop);
      ctx.fillStyle = 'rgba(220,235,255,0.55)';
      ctx.fillRect(lx - 1.2 * Sp, 58, 2.4 * Sp, Math.max(2, 0.06 * Sp));
    }
    ctx.strokeStyle = 'rgba(255,255,255,0.04)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    for (let x = Math.floor(xL / 4) * 4; x <= xR; x += 4) { const lx = Math.round(bx(x)) + 0.5; ctx.moveTo(lx, 56); ctx.lineTo(lx, floorTop); }
    ctx.stroke();
    if (hazardPattern) {
      const y0 = by(1.25), h = Math.max(4, 0.22 * Sp);
      ctx.save();
      ctx.globalAlpha = 0.5;
      ctx.translate(bx(0) % 16, 0);
      ctx.fillStyle = hazardPattern;
      ctx.fillRect(-16, y0 - h, W + 32, h);
      ctx.restore();
    }
    ctx.fillStyle = 'rgba(255,255,255,0.045)';
    ctx.font = `700 ${Math.round(clamp(0.9 * Sp, 12, 64))}px ui-sans-serif, system-ui, sans-serif`;
    ctx.textAlign = 'center'; ctx.textBaseline = 'alphabetic';
    for (let x = Math.floor(xL / 40) * 40 + 20; x <= xR + 40; x += 40) ctx.fillText('IMPACT HALL  \u00b7  TRACK 2', bx(x), by(2.7));

    // Floor surface (oblique depth band)
    g = ctx.createLinearGradient(0, floorTop, 0, groundY);
    g.addColorStop(0, '#262d36'); g.addColorStop(1, '#3a434e');
    ctx.fillStyle = g;
    ctx.fillRect(0, floorTop, W, band);
    const slant = band * (LAYER_DX / LAYER_DY);
    const x0 = cam.x - (view.cx + slant) / S - 1, x1 = cam.x + (W - view.cx) / S + 1;
    ctx.strokeStyle = 'rgba(255,255,255,0.05)';
    ctx.beginPath();
    for (let x = Math.ceil(x0); x <= x1; x++) { const sx = X(x); ctx.moveTo(sx, groundY); ctx.lineTo(sx + slant, floorTop); }
    ctx.stroke();
    ctx.fillStyle = 'rgba(255,197,49,0.55)';
    ctx.fillRect(0, floorTop + band * 0.22, W, Math.max(1, band * 0.06));
    ctx.fillStyle = 'rgba(255,255,255,0.18)';
    for (let x = Math.ceil(x0 / 2) * 2; x <= x1; x += 2) ctx.fillRect(X(x) + slant * 0.55, groundY - band * 0.55, Math.max(2, 0.9 * S), Math.max(1, band * 0.05));

    // Floor front face + ruler
    g = ctx.createLinearGradient(0, groundY, 0, H);
    g.addColorStop(0, '#1b2028'); g.addColorStop(1, '#0b0e12');
    ctx.fillStyle = g;
