    const line = (col, idx, max) => {
      cctx.strokeStyle = col; cctx.lineWidth = 1.5; cctx.beginPath();
      const stride = Math.max(1, Math.floor(n / (w * 1.5)));
      for (let i = 0; i < n; i += stride) {
        const x = (hist[i * 3] / tMax) * w, y = h - 3 - (hist[i * 3 + idx] / max) * (h - 8);
        if (i === 0) cctx.moveTo(x, y); else cctx.lineTo(x, y);
