  /* =====================================================================
   * UI
   * ===================================================================== */
  const $ = (id) => document.getElementById(id);
  const settings = Object.assign({}, DEFAULTS);
  const PHYS_KEYS = PARAMS.filter(p => p.key !== 'scale').map(p => p.key).concat(['autoBrake']);
  const panel = $('panel'), panelBody = $('panelBody');
  const inputs = {};
  const fmt = (p, v) => Number(v).toFixed(p.dec);

  function buildPanel() {
    const section = (title, parent) => {
      const t = document.createElement('div');
      t.className = 'group-title'; t.textContent = title;
      parent.appendChild(t);
    };
    const field = (p, parent) => {
      const f = document.createElement('div');
      f.className = 'field';
      f.innerHTML =
        `<div class="row"><label for="rng_${p.key}">${p.label}</label>` +
        `<div class="val"><input type="number" id="num_${p.key}" min="${p.min}" max="${p.max}" step="${p.step}" aria-label="${p.label}">` +
        `<span class="unit">${p.unit}</span></div></div>` +
        `<input type="range" id="rng_${p.key}" min="${p.min}" max="${p.max}" step="${p.step}">` +
        `<div class="meta"><span>${fmt(p, p.min)}</span><span>default ${fmt(p, p.def)}</span><span>${fmt(p, p.max)}</span></div>`;
      parent.appendChild(f);
      const rng = f.querySelector('input[type=range]'), num = f.querySelector('input[type=number]');
      inputs[p.key] = { p, f, rng, num };
      rng.addEventListener('input', () => setParam(p.key, parseFloat(rng.value)));
      num.addEventListener('change', () => setParam(p.key, parseFloat(num.value)));
      num.addEventListener('keydown', (e) => { if (e.key === 'Enter') num.blur(); });
    };
    section('Experiment', panelBody);
    for (const p of PARAMS) if (p.group === 'main') field(p, panelBody);

    const det = document.createElement('details');
    det.className = 'adv';
    det.innerHTML = '<summary class="group-title"><span>Advanced physics</span><span class="caret">\u203a</span></summary>';
    panelBody.appendChild(det);
    for (const p of PARAMS) if (p.group === 'adv') field(p, det);
    const tg = document.createElement('div');
    tg.className = 'toggle-row';
    tg.innerHTML = '<div>Auto-brake after impact<small>Wheels lock 0.25 s after first contact</small></div>' +
      '<label class="switch"><input type="checkbox" id="chkBrake"><span></span></label>';
    det.appendChild(tg);
    const chk = tg.querySelector('input');
    chk.addEventListener('change', () => setParam('autoBrake', chk.checked));

    section('View', panelBody);
    for (const p of PARAMS) if (p.group === 'view') field(p, panelBody);
    const note = document.createElement('p');
    note.className = 'note';
    note.innerHTML = 'Rigid-body solver: 480 Hz fixed step, sequential impulses with warm starting, speculative contacts and split-impulse ' +
      'position correction. Every brick is an independent body; depth layers are parallel wythes offset by half a brick. ' +
      'Identical settings replay identically.';
    panelBody.appendChild(note);
    syncInputs();
  }

  function syncInputs() {
    for (const k in inputs) {
      const { p, f, rng, num } = inputs[k];
      rng.value = settings[k];
      num.value = fmt(p, settings[k]);
      f.classList.toggle('changed', Math.abs(settings[k] - p.def) > 1e-9);
    }
    $('chkBrake').checked = !!settings.autoBrake;
  }

  function setParam(key, v) {
    if (key === 'autoBrake') settings.autoBrake = !!v;
    else {
      const p = inputs[key].p;
      if (!Number.isFinite(v)) v = settings[key];
      v = clamp(Math.round(v / p.step) * p.step, p.min, p.max);
      settings[key] = parseFloat(v.toFixed(p.dec));
    }
    syncInputs();
    if (key !== 'scale' && exp.state === 'ready') newExperiment(false);
    refreshChips();
  }

  function pendingKeys() {
    return PHYS_KEYS.filter(k => settings[k] !== exp.P[k]);
  }

  function refreshChips() {
    const P = exp.P, pend = new Set(pendingKeys());
    const chip = (keys, label, value) => {
      const isP = keys.some(k => pend.has(k));
      return `<span class="chip${isP ? ' pending' : ''}"${isP ? ' title="Changed in settings, applies on next Test"' : ''}>${label} <b>${value}</b></span>`;
    };
    $('chips').innerHTML = [
      chip(['speed'], 'Speed', `${P.speed.toFixed(1)} m/s`),
      chip(['cols', 'rows', 'layers'], 'Wall', `${P.cols} \u00d7 ${P.rows} \u00d7 ${P.layers}`),
      chip(['brickMass'], 'Brick', `${P.brickMass.toFixed(1)} kg`),
      chip(['brickW', 'brickH'], 'Size', `${P.brickW.toFixed(2)} \u00d7 ${P.brickH.toFixed(2)} m`),
      chip(['brickFriction'], '\u03bc brick', P.brickFriction.toFixed(2)),
      chip(['brickRestitution'], 'e', P.brickRestitution.toFixed(2)),
      chip(['carMass'], 'Car', `${P.carMass.toFixed(0)} kg`),
      chip(['carWidth', 'carHeight'], 'Car', `${P.carWidth.toFixed(2)} \u00d7 ${P.carHeight.toFixed(2)} m`),
      chip(['groundFriction'], '\u03bc ground', P.groundFriction.toFixed(2)),
      chip(['gravity'], 'g', `${P.gravity.toFixed(2)} m/s\u00b2`),
      chip([], 'Scale', `${settings.scale.toFixed(0)} px/m`),
    ].join('');
    const n = pend.size, note = $('pendingNote');
    note.classList.toggle('on', n > 0);
    note.textContent = n > 0
      ? `${n} change${n > 1 ? 's' : ''} pending. Press Test or Reset to apply.`
      : exp.state === 'ready' ? 'Preview matches these settings.' : 'Active test uses these settings.';
  }

  /* ---------------- Telemetry ---------------- */
  const tmCache = {};
  function setText(id, s) { if (tmCache[id] !== s) { tmCache[id] = s; $(id).textContent = s; } }
  function updateTelemetry() {
    const car = exp.car, st = exp.stats, hit = exp.impactTime >= 0;
    const v = Math.hypot(car.vx, car.vy);
    const ph = $('tmPhase');
    if (ph.dataset.phase !== exp.phase) { ph.dataset.phase = exp.phase; ph.textContent = exp.phase; }
