+      chip(['brickMass'], 'Brick', `${P.brickMass.toFixed(1)} kg`),
+      chip(['brickW', 'brickH'], 'Size', `${P.brickW.toFixed(2)} \u00d7 ${P.brickH.toFixed(2)} m`),
+      chip(['brickFriction'], '\u03bc brick', P.brickFriction.toFixed(2)),
+      chip(['brickRestitution'], 'e', P.brickRestitution.toFixed(2)),
+      chip(['carMass'], 'Car', `${P.carMass.toFixed(0)} kg`),
+      chip(['carWidth', 'carHeight'], 'Car', `${P.carWidth.toFixed(2)} \u00d7 ${P.carHeight.toFixed(2)} m`),
+      chip(['groundFriction'], '\u03bc ground', P.groundFriction.toFixed(2)),
+      chip(['gravity'], 'g', `${P.gravity.toFixed(2)} m/s\u00b2`),
+      chip([], 'Scale', `${settings.scale.toFixed(0)} px/m`),
+    ].join('');
+    const n = pend.size, note = $('pendingNote');
+    note.classList.toggle('on', n > 0);
+    note.textContent = n > 0
+      ? `${n} change${n > 1 ? 's' : ''} pending. Press Test or Reset to apply.`
+      : exp.state === 'ready' ? 'Preview matches these settings.' : 'Active test uses these settings.';
+  }
+
+  /* ---------------- Telemetry ---------------- */
+  const tmCache = {};
+  function setText(id, s) { if (tmCache[id] !== s) { tmCache[id] = s; $(id).textContent = s; } }
+  function updateTelemetry() {
+    const car = exp.car, st = exp.stats, hit = exp.impactTime >= 0;
+    const v = Math.hypot(car.vx, car.vy);
+    const ph = $('tmPhase');
+    if (ph.dataset.phase !== exp.phase) { ph.dataset.phase = exp.phase; ph.textContent = exp.phase; }
+    setText('tmTime', hit ? `t = ${exp.time.toFixed(3)} s \u00b7 T+${(exp.time - exp.impactTime).toFixed(3)}` : `t = ${exp.time.toFixed(3)} s`);
+    setText('tmSpeed', v.toFixed(1));
+    setText('tmKmh', `${(v * 3.6).toFixed(0)} km/h`);
+    setText('tmMoving', `${st.moving} / ${st.total}`);
+    setText('tmImpact', hit ? `${exp.impactSpeed.toFixed(2)} m/s` : '\u2014');
+    setText('tmDecel', hit ? `${exp.peakDecel.toFixed(1)} g` : '\u2014');
+    setText('tmCrush', hit ? `${(exp.crush * 100).toFixed(1)} cm` : '\u2014');
+    setText('tmDisplaced', `${st.displaced} (${Math.round((100 * st.displaced) / st.total)}%)`);
+    setText('tmReach', st.throw > 0.05 ? `${st.throw.toFixed(2)} m` : '\u2014');
+    setText('tmMomentum', st.peakBrickPx > 1 ? `${(st.peakBrickPx / 1000).toFixed(2)} kN\u00b7s` : '\u2014');
+    setText('tmDv', hit ? `${Math.round((100 * st.peakBrickPx) / (exp.P.carMass * exp.impactSpeed))} %` : '\u2014');
+    drawChart(exp);
+  }
+
+  /* ---------------- Experiment lifecycle ---------------- */
+  let exp = null, look = null, snapCam = true;
+  const fx = new Effects();
+  function newExperiment(start) {
+    exp = new Experiment(Object.assign({}, settings));
+    look = buildBrickLook(exp);
+    fx.reset(0x5eed);
+    acc = 0;
+    snapCam = true;
+    if (start) exp.start();
+    refreshChips();
+  }
+
+  let timeScale = 1, acc = 0, lastNow = performance.now(), simRate = 1, fpsS = 60, stepMs = 0, perfTick = 0;
+
+  function setPanel(open) {
+    panel.classList.toggle('hidden', !open);
+    document.body.classList.toggle('panel-closed', !open);
+    $('btnSettings').setAttribute('aria-pressed', String(open));
+    updateView();
+  }
+  function updateView() {
+    view.right = !panel.classList.contains('hidden') && W > 760 ? 348 : 0;
+    view.cx = (W - view.right) / 2;
+  }
+  function toggleSlow() {
+    timeScale = timeScale === 1 ? 0.2 : 1;
+    const b = $('btnSlow');
+    b.setAttribute('aria-pressed', String(timeScale !== 1));
+    b.textContent = timeScale === 1 ? 'Slow-mo' : 'Slow-mo 0.2\u00d7';
+  }
+
+  $('btnTest').addEventListener('click', () => newExperiment(true));
+  $('btnReset').addEventListener('click', () => newExperiment(false));
+  $('btnSlow').addEventListener('click', toggleSlow);
+  $('btnSettings').addEventListener('click', () => setPanel(panel.classList.contains('hidden')));
+  $('btnClosePanel').addEventListener('click', () => setPanel(false));
+  $('btnDefaults').addEventListener('click', () => {
+    Object.assign(settings, DEFAULTS);
+    syncInputs();
+    if (exp.state === 'ready') newExperiment(false);
+    refreshChips();
+  });
+  window.addEventListener('keydown', (e) => {
+    const tag = (e.target && e.target.tagName) || '';
+    if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT' || e.metaKey || e.ctrlKey || e.altKey) return;
+    if (e.code === 'Space' || e.key === 'Enter') { e.preventDefault(); newExperiment(true); }
+    else if (e.key === 'r' || e.key === 'R') newExperiment(false);
+    else if (e.key === 's' || e.key === 'S') toggleSlow();
+    else if (e.key === 'p' || e.key === 'P') setPanel(panel.classList.contains('hidden'));
+  });
+
+  function resize() {
+    DPR = Math.min(2, window.devicePixelRatio || 1);
+    W = window.innerWidth; H = window.innerHeight;
+    canvas.width = Math.round(W * DPR); canvas.height = Math.round(H * DPR);
+    groundY = Math.round(H - clamp(H * 0.17, 96, 150));
+    if (W <= 1100 && W > 760 && !panel.classList.contains('hidden') && !resize.done) setPanel(false);
+    resize.done = true;
+    updateView();
+    sizeChart();
+    snapCam = true;
+  }
+  window.addEventListener('resize', resize);
+
+  /* ---------------- Main loop ---------------- */
+  function render() {
+    ctx.setTransform(DPR, 0, 0, DPR, 0, 0);
+    drawBackground(exp);
+    drawSkids(exp);
+    drawWallFootprint(exp);
+    drawTow(exp);
+    computeCorners(exp, look);
+    drawBricks(exp, look);
+    drawCar(exp);
+    fx.draw();
+    drawOverlay(exp);
+  }
+
+  function frame(now) {
+    const rdt = Math.min(0.1, Math.max(0, (now - lastNow) / 1000));
+    lastNow = now;
+    if (rdt > 0) fpsS += (1 / rdt - fpsS) * 0.05;
+    let dtVis = rdt * timeScale;
+    if (exp.state === 'running') {
+      acc += rdt * timeScale;
+      const t0 = performance.now();
+      let n = 0;
+      while (acc >= DT && exp.state === 'running') {
+        exp.step();
+        acc -= DT;
+        n++;
+        if ((n & 3) === 0 && performance.now() - t0 > 13) { acc = Math.min(acc, DT); break; }
+      }
+      if (n) stepMs += ((performance.now() - t0) / n - stepMs) * 0.1;
+      dtVis = n * DT;
+      if (rdt > 0) simRate += ((n * DT) / (rdt * timeScale) - simRate) * 0.08;
+    } else { acc = 0; simRate += (1 - simRate) * 0.2; }
+
+    fx.consume(exp, look);
+    fx.update(dtVis);
+    updateCamera(exp, rdt, snapCam);
+    snapCam = false;
+    const sh = fx.shake * Math.min(12, 3 + cam.s * 0.07);
+    cam.shakeX = (Math.sin(now * 0.091) * 0.7 + Math.sin(now * 0.047) * 0.3) * sh;
+    cam.shakeY = Math.cos(now * 0.083) * sh * 0.6;
+    render();
+    updateTelemetry();
+    if (++perfTick % 15 === 0) {
+      const rate = exp.state === 'running' ? ` \u00b7 sim ${Math.min(1, simRate).toFixed(2)}\u00d7 real-time` : '';
+      $('perf').textContent = `${fpsS.toFixed(0)} fps \u00b7 physics ${Math.round(1 / DT)} Hz \u00b7 ${stepMs.toFixed(2)} ms/step${rate}`;
+    }
+    requestAnimationFrame(frame);
+  }
+
+  makeHazardPattern();
+  buildPanel();
+  newExperiment(false);
+  resize();
+  requestAnimationFrame((t) => { lastNow = t; frame(t); });
 })();
+})();
 </script>
