let nextId = 1;
const resetIds = () => { nextId = 1; };

// Math.sin/cos/hypot are implementation-approximated in ECMAScript; the physics only uses correctly rounded
// basic operations so the same settings replay bit-identically in every engine.
const PIO2_HI = 1.57079632673412561417e+00, PIO2_LO = 6.07710050650619224932e-11, INV_PIO2 = 6.36619772367581382433e-01;
const SC = { s: 0, c: 1 };
function sinCos(a) {
  const k = Math.round(a * INV_PIO2);
  const r = (a - k * PIO2_HI) - k * PIO2_LO, z = r * r;
  const s = r + r * z * (-1.66666666666666324348e-01 + z * (8.33333333332248946124e-03 + z * (-1.98412698298579493134e-04 +
    z * (2.75573137070700676789e-06 + z * (-2.50507602534068634195e-08 + z * 1.58969099521155010221e-10)))));
  const c = 1 - 0.5 * z + z * z * (4.16666666666666019037e-02 + z * (-1.38888888888741095749e-03 + z * (2.48015872894767294178e-05 +
    z * (-2.75573143513906633035e-07 + z * (2.08757232129817482790e-09 + z * -1.13596475577881948265e-11)))));
  const q = ((k % 4) + 4) % 4;
  if (q === 0) { SC.s = s; SC.c = c; } else if (q === 1) { SC.s = c; SC.c = -s; }
  else if (q === 2) { SC.s = -s; SC.c = -c; } else { SC.s = -c; SC.c = s; }
  return SC;
}
const len2 = (x, y) => Math.sqrt(x * x + y * y);

function createBody(o) {
  const shapes = o.shapes.map(s => ({ hx: s.hx, hy: s.hy, ox: s.ox || 0, oy: s.oy || 0, wx: 0, wy: 0 }));
  let rad = 0;
  for (const s of shapes) rad = Math.max(rad, len2(s.ox, s.oy) + len2(s.hx, s.hy));
  const a = o.a || 0, sc = sinCos(a);
  return {
    id: nextId++, idx: 0, kind: o.kind, isCar: o.kind === 'car',
    x: o.x, y: o.y, a, cs: sc.c, sn: sc.s,

