args.command:
node -e "
const fs=require('fs');const html=fs.readFileSync('index.html','utf8');
const Sim=new Function(html.match(/<script id=\"sim-core\">([\s\S]*?)<\/script>/)[1]+'\nreturn Sim;')();
const e=new Sim.Experiment(Object.assign({},Sim.DEFAULTS));e.start();let n=0;while(e.state==='running'&&n<60*480){e.step();n++;}
console.log('skid marks', e.skidMarks.length, e.skidMarks.map(m=>m.x0.toFixed(1)+'..'+m.x1.toFixed(1)).join(' '));
"
dev-browser --headless <<'EOF'
const page = await browser.getPage("crash-lab");
const errors = [];
page.on('pageerror', e => errors.push('pageerror: ' + e.message));
await page.setViewportSize({ width: 1440, height: 900 });
await page.reload();
await page.waitForTimeout(400);
const q = () => page.evaluate(() => ({ chips: document.getElementById('chips').innerText.replace(/\s+/g, ' '), note: document.getElementById('pendingNote').textContent, moving: document.getElementById('tmMoving').textContent, phase: document.getElementById('tmPhase').textContent }));
// ready: change columns via number input -> preview rebuild
await page.fill('#num_cols', '16'); await page.press('#num_cols', 'Enter');
await page.waitForTimeout(200);
const a = await q();
// out-of-range input gets clamped
await page.fill('#num_speed', '99'); await page.press('#num_speed', 'Enter');
await page.waitForTimeout(100);
const clampV = await page.inputValue('#num_speed');
await page.fill('#num_speed', '22'); await page.press('#num_speed', 'Enter');
await page.fill('#num_cols', '12'); await page.press('#num_cols', 'Enter');
// start with keyboard, then change mass mid-run -> pending
await page.click('canvas');
await page.keyboard.press('Space');
await page.waitForTimeout(300);
await page.fill('#num_brickMass', '6'); await page.press('#num_brickMass', 'Enter');
await page.waitForTimeout(100);
const b = await q();
// slow motion close-up around impact
await page.click('#btnSlow');
await page.waitForTimeout(1600);
await saveScreenshot(await page.screenshot(), 'd1-slowmo.png');
await page.waitForTimeout(900);
await saveScreenshot(await page.screenshot(), 'd2-slowmo.png');
await page.click('#btnSlow');
// reset applies pending
await page.click('#btnReset');
await page.waitForTimeout(150);
const c = await q();
await page.click('details.adv > summary');
await page.waitForTimeout(300);
await saveScreenshot(await page.screenshot(), 'd3-adv.png');
// restore defaults
await page.click('#btnDefaults');
await page.waitForTimeout(100);
const d = await q();
// small viewport
await page.setViewportSize({ width: 820, height: 600 });
await page.waitForTimeout(400);
await saveScreenshot(await page.screenshot(), 'd4-small.png');
console.log(JSON.stringify({ a, clampV, b, c, d, errors }, null, 1));
EOF

